#include <condition_variable>
#include <mutex>

std::mutex mtx;
std::condition_variable cv;
bool ready = false;

void worker() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [] { return ready; }); // Releases lock and waits
}

std::condition_variable cv;
// Ready condition updated
cv.___(); // Unblocks one thread
